CREATE TABLE patients(id INTEGER PRIMARY KEY AUTOINCREMENT,first_name TEXT NOT NULL,last_name TEXT NOT NULL,dob TEXT,sex TEXT,phone TEXT,curp TEXT,blood_type TEXT,occupation TEXT,marital_status TEXT,address TEXT,emergency_contact TEXT,emergency_phone TEXT,allergies TEXT,personal_history TEXT,family_history TEXT,surgical_history TEXT,chronic_meds TEXT,notes TEXT,is_archived INTEGER NOT NULL DEFAULT 0,is_deceased INTEGER NOT NULL DEFAULT 0,deceased_at TEXT,death_notes TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX idx_patient_name ON patients(last_name,first_name);
CREATE TABLE consultations(id INTEGER PRIMARY KEY AUTOINCREMENT,patient_id INTEGER NOT NULL,date TEXT NOT NULL,systolic REAL,diastolic REAL,heart_rate REAL,respiratory_rate REAL,temperature REAL,spo2 REAL,weight REAL,height REAL,bmi REAL,glucose REAL,reason TEXT,illness TEXT,physical_exam TEXT,diagnoses TEXT,treatment TEXT,studies TEXT,plan TEXT,created_at TEXT NOT NULL,FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE CASCADE);
CREATE INDEX idx_consult_patient ON consultations(patient_id,date DESC);
CREATE TABLE emergencies(id INTEGER PRIMARY KEY AUTOINCREMENT,patient_id INTEGER NOT NULL,date TEXT NOT NULL,triage TEXT,pain REAL,glasgow REAL,systolic REAL,diastolic REAL,heart_rate REAL,respiratory_rate REAL,temperature REAL,spo2 REAL,glucose REAL,reason TEXT,brief_history TEXT,physical_exam TEXT,diagnoses TEXT,treatment TEXT,studies TEXT,evolution TEXT,disposition TEXT,disposition_notes TEXT,created_at TEXT NOT NULL,FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE CASCADE);
CREATE TABLE hospitalizations(id INTEGER PRIMARY KEY AUTOINCREMENT,patient_id INTEGER NOT NULL,admitted_at TEXT NOT NULL,discharged_at TEXT,room TEXT,bed TEXT,reason TEXT,diagnoses TEXT,exam TEXT,plan TEXT,discharge_diagnoses TEXT,discharge_summary TEXT,discharge_treatment TEXT,discharge_recommendations TEXT,status TEXT NOT NULL DEFAULT "hospitalizado",created_at TEXT NOT NULL,FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE CASCADE);
CREATE TABLE progress_notes(id INTEGER PRIMARY KEY AUTOINCREMENT,hospitalization_id INTEGER NOT NULL,date TEXT NOT NULL,subjective TEXT,objective TEXT,assessment TEXT,plan TEXT,systolic REAL,diastolic REAL,heart_rate REAL,respiratory_rate REAL,temperature REAL,spo2 REAL,glucose REAL,created_at TEXT NOT NULL,FOREIGN KEY(hospitalization_id) REFERENCES hospitalizations(id) ON DELETE CASCADE);
CREATE TABLE medical_orders(id INTEGER PRIMARY KEY AUTOINCREMENT,hospitalization_id INTEGER NOT NULL,date TEXT NOT NULL,diet TEXT,activity TEXT,fluids TEXT,oxygen TEXT,medications TEXT,monitoring TEXT,studies TEXT,nursing TEXT,other TEXT,created_at TEXT NOT NULL,FOREIGN KEY(hospitalization_id) REFERENCES hospitalizations(id) ON DELETE CASCADE);
CREATE TABLE documents(id INTEGER PRIMARY KEY AUTOINCREMENT,patient_id INTEGER NOT NULL,date TEXT NOT NULL,type TEXT NOT NULL,title TEXT NOT NULL,content TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE CASCADE);
CREATE TABLE cie10(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,chapter TEXT,search_text TEXT NOT NULL,favorite INTEGER NOT NULL DEFAULT 0);
CREATE INDEX idx_cie_code ON cie10(code);
CREATE INDEX idx_cie_search ON cie10(search_text);
CREATE TABLE appointments(id INTEGER PRIMARY KEY AUTOINCREMENT,patient_id INTEGER NOT NULL,start_at TEXT NOT NULL,reason TEXT,notes TEXT,status TEXT NOT NULL DEFAULT "programada",notify_minutes_before INTEGER NOT NULL DEFAULT 30,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE CASCADE);
CREATE INDEX idx_appointments_start ON appointments(start_at);
CREATE TABLE audit(id INTEGER PRIMARY KEY AUTOINCREMENT,date TEXT NOT NULL,action TEXT NOT NULL,detail TEXT);
CREATE TABLE favorites(id INTEGER PRIMARY KEY AUTOINCREMENT,type TEXT NOT NULL,name TEXT NOT NULL,content TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE medications(id INTEGER PRIMARY KEY AUTOINCREMENT,generic_name TEXT NOT NULL,brand_name TEXT,form TEXT,strength TEXT,presentation TEXT,registration TEXT,status TEXT,source TEXT,favorite INTEGER NOT NULL DEFAULT 0,use_count INTEGER NOT NULL DEFAULT 0,last_used_at TEXT,search_text TEXT NOT NULL);
CREATE INDEX idx_med_search ON medications(search_text);
CREATE INDEX idx_med_generic ON medications(generic_name);
CREATE TABLE app_settings(setting_key TEXT PRIMARY KEY,setting_value TEXT);